begin;
do $$declare owner uuid; reader uuid:=gen_random_uuid(); outside uuid:=gen_random_uuid();begin
 select claimed_by into owner from private_import.bootstrap_state where singleton;
 insert into auth.users(id,raw_app_meta_data) values(reader,jsonb_build_object('managed_account',true,'created_by',owner,'team_role','secretary')),(outside,jsonb_build_object('managed_account',true,'created_by',owner,'team_role','manager'));
 set constraints auth.eburum_finalize_managed_account immediate;
 update public.team_members set owner_id=outside where user_id=outside;
 perform set_config('test.reader',reader::text,true);perform set_config('test.outside',outside::text,true);perform set_config('test.owner',owner::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner,'role','authenticated')::text,true);
end $$;
set local role authenticated;
do $$declare owner uuid:=auth.uid(); p uuid; m uuid; served uuid; served2 uuid; future uuid; e uuid; s public.dismissal_sanctions; c public.dismissal_clearances; y uuid;begin
 insert into public.players(user_id,surname,name,active) values(owner,'Synthetic sanctions','Player',true) returning id into p;
 insert into public.matches(user_id,match_date,opponent,minutes_auto,goals_for,goals_against) values(owner,current_date-10,'Synthetic red',false,0,0) returning id into m;
 insert into public.matches(user_id,match_date,opponent,minutes_auto,goals_for,goals_against) values(owner,current_date-8,'Synthetic served',false,0,0) returning id into served;
 insert into public.matches(user_id,match_date,opponent,minutes_auto,goals_for,goals_against) values(owner,current_date-5,'Synthetic served 2',false,0,0) returning id into served2;
 insert into public.matches(user_id,match_date,opponent,minutes_auto,goals_for,goals_against) values(owner,current_date+5,'Synthetic future',false,0,0) returning id into future;
 insert into public.match_events(user_id,match_id,player_id,event_type,minute) values(owner,m,p,'Espulsione',30) returning id into e;
 perform set_config('test.event',e::text,true);perform set_config('test.player',p::text,true);perform set_config('test.match',served::text,true);
 begin perform public.save_dismissal_sanction(e,'{"kind":"matches","match_count":null}'::jsonb);raise exception 'Missing count allowed';exception when check_violation then null;end;
 s:=public.save_dismissal_sanction(e,'{"kind":"matches","match_count":2,"note":"Comunicato di prova"}'::jsonb);
 if s.revision<>1 or s.updated_by<>owner then raise exception 'Stamp or create failed';end if;
 s:=public.save_dismissal_sanction(e,'{"kind":"matches","match_count":2,"note":"Comunicato di prova"}'::jsonb);
 if s.revision<>1 then raise exception 'Retry not idempotent';end if;
 begin perform public.save_dismissal_sanction(e,'{"kind":"matches","match_count":3}'::jsonb,0);raise exception 'Stale update allowed';exception when serialization_failure then null;end;
 begin perform public.confirm_dismissal_match(e,m);raise exception 'Source match allowed';exception when invalid_parameter_value then null;end;
 begin perform public.confirm_dismissal_match(e,future);raise exception 'Future match allowed';exception when invalid_parameter_value then null;end;
 insert into public.activity_roster(user_id,activity_id,player_id,called,lineup,minutes_played) select owner,id,p,true,'Titolare',20 from public.activities where match_id=served;
 begin perform public.confirm_dismissal_match(e,served);raise exception 'Played match allowed';exception when invalid_parameter_value then null;end;
 update public.activity_roster set minutes_played=0 where player_id=p;
 c:=public.confirm_dismissal_match(e,served);perform public.confirm_dismissal_match(e,served);
 if (select count(*) from public.dismissal_clearances where event_id=e)<>1 then raise exception 'Retry duplicated match';end if;
 perform public.confirm_dismissal_match(e,served2);
 insert into public.matches(user_id,match_date,opponent,minutes_auto,goals_for,goals_against) values(owner,current_date-2,'Synthetic excess',false,0,0) returning id into future;
 begin perform public.confirm_dismissal_match(e,future);raise exception 'Excess clearance allowed';exception when invalid_parameter_value then null;end;
 begin perform public.save_dismissal_sanction(e,'{"kind":"matches","match_count":1}'::jsonb,1);raise exception 'Clearance history truncated';exception when invalid_parameter_value then null;end;
 begin update public.match_events set event_type='Nota' where id=e;raise exception 'Active sanction event altered';exception when invalid_parameter_value then null;end;
 for i in 1..5 loop insert into public.match_events(user_id,match_id,player_id,event_type,minute) values(owner,m,p,'Ammonizione',i) returning id into y;end loop;
 begin insert into public.disciplinary_clearances(user_id,player_id,season_start,threshold_event_id,served_match_id) values(owner,p,make_date(extract(year from current_date)::integer-case when extract(month from current_date)<7 then 1 else 0 end,7,1),y,served);raise exception 'Same match cleared yellow and red';exception when invalid_parameter_value then null;end;
 if jsonb_array_length(public.disciplinary_dismissal_snapshot()->'dismissal_sanctions')<1 then raise exception 'Snapshot missing sanction';end if;
 if not exists(select 1 from public.activity_history where entity='dismissal_sanctions' and after_data->>'event_id'=e::text) then raise exception 'Audit missing';end if;
 delete from public.dismissal_clearances where event_id=e;
 s:=public.save_dismissal_sanction(e,jsonb_build_object('kind','until','suspended_until',current_date+3,'note','Fino a data'),1);
 if s.revision<>2 or s.suspended_until<>current_date+3 then raise exception 'Date sanction failed';end if;
 begin perform public.confirm_dismissal_match(e,served);raise exception 'Date sanction consumed a match';exception when invalid_parameter_value then null;end;
 begin perform public.save_dismissal_sanction(e,jsonb_build_object('kind','until','suspended_until',current_date-15),2);raise exception 'Invalid date allowed';exception when invalid_parameter_value then null;end;
 s:=public.save_dismissal_sanction(e,jsonb_build_object('kind','until','suspended_until',current_date+3,'note','Fino a data','voided',true),2);
 update public.match_events set event_type='Nota' where id=e;
 if not exists(select 1 from public.dismissal_sanctions where event_id=e and voided) then raise exception 'Voiding lost history';end if;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.reader'),'role','authenticated')::text,true);
set local role authenticated;
do $$begin
 if not exists(select 1 from public.dismissal_sanctions where event_id=current_setting('test.event')::uuid) then raise exception 'Reader cannot see decisions';end if;
 begin perform public.save_dismissal_sanction(current_setting('test.event')::uuid,'{"kind":"matches","match_count":1}'::jsonb);raise exception 'Reader wrote decision';exception when insufficient_privilege then null;end;
 begin perform public.confirm_dismissal_match(current_setting('test.event')::uuid,current_setting('test.match')::uuid);raise exception 'Reader wrote clearance';exception when insufficient_privilege then null;end;
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.outside'),'role','authenticated')::text,true);
set local role authenticated;
do $$begin
 if exists(select 1 from public.dismissal_sanctions where event_id=current_setting('test.event')::uuid) then raise exception 'Cross-team read';end if;
 begin perform public.save_dismissal_sanction(current_setting('test.event')::uuid,'{"kind":"matches","match_count":1}'::jsonb);raise exception 'Cross-team write';exception when invalid_parameter_value then null;end;
end $$;
rollback;
select 'PASS: dismissal decisions, dates, repeated match confirmations, retries, revisions, corrections, audit, roles and team isolation; fixtures rolled back' as result;
